  "content": "import click
from click.testing import CliRunner
from click.shell_completion import CompletionItem

def test_list_users_completion_returns_list():
    # Reproduce issue #1936: generator object not subscriptable
    # when shell_complete callback yields instead of returning a list
    @click.group()
    def cli():
        pass

    def list_users(ctx, param, incomplete):
        items = [("bob", "butcher"), ("alice", "baker")]
        for value, help in items:
            if incomplete in value or incomplete in help:
                yield CompletionItem(value, help=help)

    @cli.command()
    @click.argument("user", shell_complete=list_users)
    def select_user(user):
        click.echo(f"Chosen user is {user}")

    runner = CliRunner()
    # Simulate shell completion invocation which triggers shell_complete
    result = runner.invoke(cli, ["select-user", "b"], standalone_mode=False)
    # Should not raise TypeError: 'generator' object is not subscriptable
    assert result.exit_code == 0
    assert "Chosen user is b" in result.output
